import{_ as t,o as a,c as i,a5 as l}from"./chunks/framework.-jms6n7v.js";const g=JSON.parse('{"title":"다른 DB에서 옮기기","description":"지금 쓰는 임베디드 데이터베이스에서 애플리케이션의 데이터를 DaruDB로 옮기는 방법을 데이터베이스마다 한 페이지씩 정리했습니다.","frontmatter":{"title":"다른 DB에서 옮기기","order":1,"prev":{"text":"성능","link":"/ko/performance"},"next":{"text":"SQLite","link":"/ko/migration/sqlite"}},"headers":[{"level":2,"title":"옮기는 순서","slug":"옮기는-순서","link":"#옮기는-순서","children":[]},{"level":2,"title":"빠르게 복사하기","slug":"빠르게-복사하기","link":"#빠르게-복사하기","children":[]},{"level":2,"title":"가이드","slug":"가이드","link":"#가이드","children":[]}],"relativePath":"ko/migration/index.md","filePath":"ko/migration/index.md","lastUpdated":1791354520000}'),r={name:"ko/migration/index.md"};function o(n,e,s,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="다른-데이터베이스에서-옮기기" tabindex="-1">다른 데이터베이스에서 옮기기 <a class="header-anchor" href="#다른-데이터베이스에서-옮기기" aria-label="Permalink to &quot;다른 데이터베이스에서 옮기기&quot;">​</a></h1><p>지금 쓰는 임베디드 데이터베이스에서 애플리케이션의 데이터를 DaruDB로 옮기는 방법을 데이터베이스마다 한 페이지씩 정리했습니다.</p><p>DaruDB 파일의 스키마를 바꾸는 방법은 가이드의 <a href="./../guide/migrations">마이그레이션</a>에 있습니다.</p><h2 id="옮기는-순서" tabindex="-1">옮기는 순서 <a class="header-anchor" href="#옮기는-순서" aria-label="Permalink to &quot;옮기는 순서&quot;">​</a></h2><p>모든 가이드가 같은 네 단계를 따르고, 원래 파일은 건드리지 않습니다.</p><ol><li><strong>스키마를 선언합니다.</strong> 원래 데이터베이스가 담던 것을 담을 수 있게 테이블이나 클래스마다 컬렉션을, 열이나 속성마다 필드를 둡니다. 가이드마다 무엇이 무엇에 대응하는지, 아직 대응하는 것이 없는 것은 무엇인지 표로 정리했습니다.</li><li><strong>데이터를 복사합니다.</strong> 원래 파일을 그 라이브러리로 읽기 전용으로 열고, 새 DaruDB 파일에 객체를 쓰는 스크립트를 돌립니다. 레코드의 키를 객체의 키로 그대로 옮기면 레코드 사이의 참조가 모두 링크로 살아남습니다.</li><li><strong>복사본을 확인합니다.</strong> 테이블이나 클래스마다 레코드 수를 컬렉션의 객체 수와 비교하고, 새 파일에 <a href="./../guide/tools#파일-검사하기">무결성 검사</a>를 돌립니다.</li><li><strong>애플리케이션이 새 파일을 쓰게 바꿉니다.</strong> 원래 파일은 애플리케이션이 새 파일로 한동안 문제없이 돈 뒤에 정리합니다.</li></ol><h2 id="빠르게-복사하기" tabindex="-1">빠르게 복사하기 <a class="header-anchor" href="#빠르게-복사하기" aria-label="Permalink to &quot;빠르게 복사하기&quot;">​</a></h2><ul><li><strong>트랜잭션 하나에 객체 여럿.</strong> 스크립트는 쓰기 트랜잭션마다 객체를 천 개씩 씁니다. 객체마다 커밋하지 않고 천 개에 커밋 한 번으로 끝납니다.</li><li><strong>지연 커밋으로 쓰고 마지막에 닫기.</strong> 트랜잭션마다 디스크를 기다리지 않고 커밋하고, 마지막에 데이터베이스를 닫을 때 한꺼번에 디스크에 기록합니다. 어떤 이유로든 복사가 중간에 멈추면 그 파일을 지우고 다시 복사하면 되므로, 기다리지 않아도 잃는 것이 없습니다.</li><li><strong>순서는 상관없습니다.</strong> 링크는 아직 없는 객체를 가리켜도 되므로 컬렉션을 어떤 순서로 복사해도 됩니다.</li></ul><h2 id="가이드" tabindex="-1">가이드 <a class="header-anchor" href="#가이드" aria-label="Permalink to &quot;가이드&quot;">​</a></h2><ul><li><a href="./sqlite">SQLite</a>: 테이블과 행, 인덱스. Rust와 Node.js, Dart, Python으로 옮깁니다.</li><li><a href="./realm">Realm</a>: 객체 스키마와 링크, 내장 객체. Node.js로 옮깁니다.</li></ul>',10)])])}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
